import type { MetadataRoute } from "next";
import { MANIFEST_BACKGROUND_COLOR, MANIFEST_THEME_COLOR } from "../lib/pwa-colors";

// Served as /manifest.webmanifest. Icons are generated by scripts/generate-pwa-assets.mjs.
export default function manifest(): MetadataRoute.Manifest {
  return {
    id: "/",
    name: "Holdings",
    short_name: "Holdings",
    description: "A private stock and ETF portfolio tracker.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    background_color: MANIFEST_BACKGROUND_COLOR,
    theme_color: MANIFEST_THEME_COLOR,
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      { src: "/icons/icon-maskable-512.png", sizes: "512x512", type: "image/png", purpose: "maskable" },
    ],
  };
}
